</code></pre> GET categorieDELETE manufacturers /app/routes/categories/GetCategorie.php<pre><code>#[Route(Method::Get, ["api", "categories", "{url_name}:{string}"], [], ContentTypes::Json)]
class GetCategories extends Controller {
function manageRequest(Request $request, Params $params): Response {
    $url_name = $params-&gt;getString("url_name");

    $result = preg_replace('/\s+/', '', $url_name);

    if ($result === "") {
        throw new BadRequest("Dare una categoria valida");
    }

    $db = \DatabaseUtil\Database::getDatabase();

    $pr = $db-&gt;prepare("
                    SELECT 
                        C.id,
                        C.name,
                        C.url_name,
                        C.max_per_build,
                        CS.spec_key,
                        CS.spec_label,
                        CS.unit
                    FROM categories AS C
                    LEFT JOIN category_specs AS CS 
                        ON CS.category_id = C.id
                    WHERE C.url_name = ?
                ");

    $success = $pr-&gt;execute([$url_name]);
    $rows = $pr-&gt;fetchAll(PDO::FETCH_ASSOC);

    if (!$success || empty($rows)) {
        throw new NotFound("Categoria non esistente");
    }

    $category = [
        "id" =&gt; $rows[0]["id"],
        "name" =&gt; $rows[0]["name"],
        "url_name" =&gt; $rows[0]["url_name"],
        "specs" =&gt; []
    ];

    foreach ($rows as $row) {
        if ($row["spec_key"] !== null) {
            $category["specs"][] = [
                "key" =&gt; $row["spec_key"],
                "label" =&gt; $row["spec_label"],
                "unit" =&gt; $row["unit"]
            ];
        }
    }

    return Response::new()
        -&gt;ok()
        -&gt;body($category);
}}
</code></pre> /app/routes/manufacturers/DeleteManufacturers.php<pre><code>#[Route(Method::Delete, ["api", "manufacturers", "{url_name}:{string}"], [OwnerAuthMiddleware::class], ContentTypes::Json)]
class DeleteManufacturers extends Controller {
    function manageRequest(Request $request, Params $params): Response {
        $name = $params-&gt;getString("url_name");
        if(!isset($name)){
            throw new BadRequest("Inserisci un nome nel body");
        }

        $db = \DatabaseUtil\Database::getDatabase();


        $pr = $db-&gt;prepare("SELECT * FROM manufacturers WHERE url_name=?");

        $pr-&gt;execute([$name]);
        $exists = $pr-&gt;fetch(PDO::FETCH_ASSOC);

        if(!$exists){
            throw new BadRequest("Azienda non esistente");
        }

        $pr = $db-&gt;prepare("DELETE FROM manufacturers WHERE url_name=?");

        $success = $pr-&gt;execute([$name]);

        if($success){
            $res = Response::new()
                -&gt;noContent();
        }else{
            throw new BadRequest("Error Processing Request");
        }
        return $res;
}}
