Abstract Middleware /framework/Middleware.php<pre><code>abstract class Middleware {
    public function __invoke(Request $request, callable $next){
        if($this-&gt;manageRequest($request))
            $next();
        else 
            Router::sendResponse($this-&gt;getErrorResponse($request), ContentTypes::Json);
    }

    /**
     * Override per restituire una risposta custom in caso si restituisca false in manageRequest
     * @return Response
     */
    public function getErrorResponse(Request $request): Response{
        return Response::new()
        -&gt;badRequest();
    }

    /**
     * Da gestire la richiesta, 
     * dopo questo metodo verrà chiamata la successa successiva se restituisci true,
     * altrimenti ferma la richiesta se restituisci
     * @param Request $request
     * @return bool
     */
    public abstract function manageRequest(Request $request): bool;
}
</code></pre> AuthOwnerAuth /app/middlewares/Authmiddleware.php<pre><code>class AuthMiddleware extends Middleware {
