/framework/RouteBuilder<pre><code>public static function build(string $path, ?Request $request = new Request()): array|null {
    $before = get_declared_classes();
    $iterator = new \RecursiveIteratorIterator(
        new \RecursiveDirectoryIterator($path)
    );

    try {
        foreach ($iterator as $file) {
            if ($file-&gt;isFile() &amp;&amp; $file-&gt;getExtension() === 'php') {
                require_once $file-&gt;getPathname();
            }
        }

    } catch (\Throwable $th) {
        $res = Response::new()
            -&gt;internalServerError()
            -&gt;body(["description" =&gt; "route duplicate"]);
        Router::sendResponse($res, ContentTypes::Json);
    }

    $after = get_declared_classes();
    $newClasses = array_diff($after, $before);

    $routes = [];

    // Istanzia tutte le route in base a quelle in cache(1)

    $indexedRoutes = [];

    foreach ($routes as $route) {
        $node = &amp;$indexedRoutes;

        $pattern = $route-&gt;getPattern();
        $lastIndex = count($pattern) - 1;

        if (empty($pattern)) {
            $indexedRoutes['_' . $route-&gt;getMethod()] = $route-&gt;toArray();
        }

        //[...]
        //Foreach per la creazione dell'array php della trie delle routes
    }

    if (!is_dir(__DIR__ . '/cache')) {
        mkdir(__DIR__ . '/cache', 0775, true);
    }

    $p = __DIR__ . '/cache/routes.php';


    $data = "&lt;?php\nreturn " . VarExporter::export($indexedRoutes) . ";\n";
    file_put_contents($p, $data);


    $path = __DIR__ . '/cache/routes.php';
    return (require $path);
}
